import { t as Role } from "../../../../chunks/schema.js";
import { t as getConfig } from "../../../../chunks/config.js";
import { t as client } from "../../../../chunks/prisma.js";
import { l as requireRole } from "../../../../chunks/auth.js";
// src/routes/admin/users/+page.server.ts
var load = async () => {
	const user = await requireRole(Role.ADMIN);
	const usersQuery = client.user.findMany({ select: {
		id: true,
		username: true,
		name: true,
		email: true,
		role: { select: { id: true } },
		UserGroupMembership: { select: { group: { select: { name: true } } } }
	} });
	const [users, groups, config] = await Promise.all([
		usersQuery,
		client.group.findMany(),
		getConfig()
	]);
	return {
		user: {
			isAdmin: true,
			...user
		},
		users: users.map((user) => ({
			isAdmin: user.role.id === Role.ADMIN,
			groups: user.UserGroupMembership.map(({ group }) => group.name),
			...user
		})),
		config,
		groups
	};
};
export { load };
